  1→package auth
  2→
  3→// NTLMSSP 服务端 Provider —— 把 SPNEGO 外壳、NTLM 报文层与 NTLMv2 校验
  4→// 拼成 auth.Provider / auth.Context。
  5→//
  6→// 多轮握手（MS-SMB2 §3.3.5.5）：
  7→//
  8→//	客户端 NEGOTIATE(Type1) → 服务端 CHALLENGE(Type2)  [done=false]
  9→//	客户端 AUTHENTICATE(Type3) → 成功                   [done=true]
 10→//
 11→// done=false 由 server 层翻译成 STATUS_MORE_PROCESSING_REQUIRED。
 12→
 13→import (
 14→	"crypto/rand"
 15→	"crypto/subtle"
 16→	"io"
 17→	"time"
 18→)
 19→
 20→// Options 配置 NTLMSSP Provider。
 21→type Options struct {
 22→	// Store 是账户后端。为 nil 时只能进行匿名认证。
 23→	Store AccountStore
 24→
 25→	// ServerName 是 NetBIOS 计算机名，进 CHALLENGE 的 TargetName
 26→	// 与 MsvAvNbComputerName。
 27→	ServerName string
 28→	// DomainName 是 NetBIOS 工作组/域名，进 MsvAvNbDomainName。
 29→	DomainName string
 30→	// DNSComputerName / DNSDomainName 进对应的 AV_PAIR。
 31→	// 留空则退化为 ServerName / DomainName。
 32→	DNSComputerName string
 33→	DNSDomainName   string
 34→
 35→	// AllowAnonymous 允许匿名（null）会话。默认关闭。
 36→	AllowAnonymous bool
 37→
 38→	// Rand 是随机源，nil 表示 crypto/rand.Reader。仅测试需要注入。
 39→	Rand io.Reader
 40→	// Now 返回当前时间，nil 表示 time.Now。仅测试需要注入。
 41→	Now func() time.Time
 42→}
 43→
 44→// NTLMProvider 实现 Provider。构造后只读，并发安全。
 45→type NTLMProvider struct {
 46→	opts    Options
 47→	initial []byte
 48→}
 49→
 50→var _ Provider = (*NTLMProvider)(nil)
 51→
 52→// NewNTLMProvider 创建 NTLMSSP(+SPNEGO) 认证提供者。
 53→func NewNTLMProvider(opts Options) *NTLMProvider {
 54→	if opts.Rand == nil {
 55→		opts.Rand = rand.Reader
 56→	}
 57→	if opts.Now == nil {
 58→		opts.Now = time.Now
 59→	}
 60→	if opts.DNSComputerName == "" {
 61→		opts.DNSComputerName = opts.ServerName
 62→	}
 63→	if opts.DNSDomainName == "" {
 64→		opts.DNSDomainName = opts.DomainName
 65→	}
 66→	return &NTLMProvider{
 67→		opts: opts,
 68→		// 只宣告 NTLMSSP：本项目不做 Kerberos（依赖系统 krb5 配置会违反 C8）。
 69→		initial: NegTokenInit2([][]byte{oidNTLMSSP}),
 70→	}
 71→}
 72→
 73→// Name 返回机制名，用于日志。
 74→func (p *NTLMProvider) Name() string { return "ntlmssp" }
 75→
 76→// InitialToken 返回 SMB2 NEGOTIATE Response 里的 SPNEGO negTokenInit2。
 77→//
 78→// 返回的切片是内部缓冲的副本，调用方可自由持有。
 79→func (p *NTLMProvider) InitialToken() []byte {
 80→	out := make([]byte, len(p.initial))
 81→	copy(out, p.initial)
 82→	return out
 83→}
 84→
 85→// NewContext 创建一次新的认证会话。
 86→func (p *NTLMProvider) NewContext() Context { return &ntlmContext{p: p} }
 87→
 88→// ntlmContext 是一次会话的握手状态。非并发安全（由单个会话串行使用）。
 89→type ntlmContext struct {
 90→	p *NTLMProvider
 91→
 92→	// spnego 表示客户端使用了 SPNEGO 外壳（否则是裸 NTLMSSP）。
 93→	spnego bool
 94→	// mechSent 表示已经在 negTokenResp 里回过 supportedMech。
 95→	mechSent bool
 96→
 97→	// negotiateMsg / challengeMsg 是 MIC 计算需要的原始 NTLM 报文字节。
 98→	negotiateMsg    []byte
 99→	challengeMsg    []byte
100→	serverChallenge [8]byte
101→
102→	identity   *Identity
103→	sessionKey []byte
104→	done       bool
105→}
106→
107→var _ Context = (*ntlmContext)(nil)
108→
109→// Identity 返回认证成功后的身份，未完成时为 nil。
110→func (c *ntlmContext) Identity() *Identity { return c.identity }
111→
112→// SessionKey 返回 16 字节 ExportedSessionKey；匿名/guest 会话为全零。
113→func (c *ntlmContext) SessionKey() []byte {
114→	if c.sessionKey == nil {
115→		return make([]byte, SessionKeyLen)
116→	}
117→	return c.sessionKey
118→}
119→
120→// Step 处理一个 GSS-API token。
121→func (c *ntlmContext) Step(in []byte) ([]byte, bool, error) {
122→	if c.done {
123→		return nil, true, ErrInvalidToken
124→	}
125→
126→	tok, err := ParseSPNEGO(in)
127→	if err != nil {
128→		return nil, false, err
129→	}
130→	c.spnego = !tok.Raw
131→
132→	// 客户端只列了机制没带 token（或带的是 Kerberos token）：
133→	// 按 RFC 4178 §4.2.2 回 accept-incomplete + supportedMech，让它改发 NTLM。
134→	if len(tok.Token) == 0 || !IsNTLMSSP(tok.Token) {
135→		if tok.Init && len(tok.MechTypes) > 0 && !tok.HasMech(oidNTLMSSP) {
136→			return nil, false, ErrMechUnsupported
137→		}
138→		if !c.spnego {
139→			return nil, false, ErrInvalidToken
140→		}
141→		c.mechSent = true
142→		return NegTokenResp(NegAcceptIncomplete, oidNTLMSSP, nil, nil), false, nil
143→	}
144→
145→	mt, err := MessageType(tok.Token)
146→	if err != nil {
147→		return nil, false, err
148→	}
149→	switch mt {
150→	case MsgTypeNegotiate:
151→		return c.handleNegotiate(tok.Token)
152→	case MsgTypeAuthenticate:
153→		return c.handleAuthenticate(tok.Token)
154→	default:
155→		return nil, false, ErrInvalidToken
156→	}
157→}
158→
159→// wrap 按当前外壳形态包装服务端要回的 NTLM 报文。
160→func (c *ntlmContext) wrap(state NegState, ntlm []byte) []byte {
161→	if !c.spnego {
162→		return ntlm
163→	}
164→	var mech []byte
165→	if !c.mechSent {
166→		// supportedMech 只在第一次回应时携带（RFC 4178 §4.2.2）。
167→		mech = oidNTLMSSP
168→		c.mechSent = true
169→	}
170→	return NegTokenResp(state, mech, ntlm, nil)
171→}
172→
173→// handleNegotiate 处理 Type 1，生成 Type 2 CHALLENGE。
174→func (c *ntlmContext) handleNegotiate(msg []byte) ([]byte, bool, error) {
175→	neg, err := ParseNegotiateMessage(msg)
176→	if err != nil {
177→		return nil, false, err
178→	}
179→	c.negotiateMsg = append([]byte(nil), msg...)
180→
181→	if _, err := io.ReadFull(c.p.opts.Rand, c.serverChallenge[:]); err != nil {
182→		return nil, false, err
183→	}
184→
185→	ch := &ChallengeMessage{
186→		TargetName:      c.p.opts.ServerName,
187→		Flags:           c.challengeFlags(neg.Flags),
188→		ServerChallenge: c.serverChallenge,
189→		TargetInfo:      c.targetInfo(),
190→		Version: Version{
191→			// 宣告一个通用的现代版本号，只影响客户端的展示与兼容分支。
192→			Major: 6, Minor: 1, Build: 7601, NTLMRevision: NTLMRevisionCurrent,
193→		},
194→	}
195→	c.challengeMsg = ch.Marshal()
196→	return c.wrap(NegAcceptIncomplete, c.challengeMsg), false, nil
197→}
198→
199→// challengeFlags 计算 CHALLENGE 里回给客户端的协商标志。
200→//
201→// 原则：只保留双方都支持的位，并强制打开 NTLMv2 必需的
202→// EXTENDED_SESSIONSECURITY / TARGET_INFO / ALWAYS_SIGN。
203→func (c *ntlmContext) challengeFlags(client NegotiateFlags) NegotiateFlags {
204→	f := NegotiateNTLM |
205→		NegotiateRequestTarget |
206→		NegotiateTargetTypeServer |
207→		NegotiateTargetInfo |
208→		NegotiateAlwaysSign |
209→		NegotiateExtendedSessionSecurity |
210→		NegotiateVersion |
211→		Negotiate128 |
212→		Negotiate56
213→
214→	// 字符集：优先 Unicode。
215→	if client.Has(NegotiateUnicode) || !client.Has(NegotiateOEM) {
216→		f |= NegotiateUnicode
217→	} else {
218→		f |= NegotiateOEM
219→	}
220→
221→	// 这些位必须**镜像客户端的请求**，否则密钥协商会不一致。
222→	for _, bit := range []NegotiateFlags{
223→		NegotiateSign, NegotiateSeal, NegotiateKeyExch, NegotiateIdentify,
224→	} {
225→		if client.Has(bit) {
226→			f |= bit
227→		}
228→	}
229→	return f
230→}
231→
232→// targetInfo 构造 CHALLENGE 的 TargetInfo。
233→//
234→// MS-NLMP §2.2.2.1：前四项（NbDomainName / NbComputerName /
235→// DnsDomainName / DnsComputerName）不全时部分 Windows 客户端会拒绝，
236→// 因此一律带齐，并附上 Timestamp（NTLMv2 需要它来做重放窗口判断）。
237→func (c *ntlmContext) targetInfo() AvPairs {
238→	o := &c.p.opts
239→	return AvPairs{
240→		{ID: MsvAvNbDomainName, Value: utf16le(o.DomainName)},
241→		{ID: MsvAvNbComputerName, Value: utf16le(o.ServerName)},
242→		{ID: MsvAvDnsDomainName, Value: utf16le(o.DNSDomainName)},
243→		{ID: MsvAvDnsComputerName, Value: utf16le(o.DNSComputerName)},
244→		{ID: MsvAvTimestamp, Value: encodeFiletime(filetimeNow(o.Now()))},
245→	}
246→}
247→
248→// handleAuthenticate 处理 Type 3，完成校验。
249→func (c *ntlmContext) handleAuthenticate(msg []byte) ([]byte, bool, error) {
250→	m, err := ParseAuthenticateMessage(msg)
251→	if err != nil {
252→		return nil, false, err
253→	}
254→	if c.challengeMsg == nil {
255→		// 没发过 CHALLENGE 就收到 AUTHENTICATE，状态机被跳步。
256→		return nil, false, ErrInvalidToken
257→	}
258→
259→	if m.IsAnonymous() {
260→		if !c.p.opts.AllowAnonymous {
261→			return nil, false, ErrLogonFailure
262→		}
263→		c.identity = &Identity{Workstation: m.Workstation, Anonymous: true}
264→		c.sessionKey = make([]byte, SessionKeyLen)
265→		c.done = true
266→		return c.wrap(NegAcceptCompleted, nil), true, nil
267→	}
268→
269→	acct, lookupErr := c.lookup(m.UserName, m.DomainName)
270→
271→	// 用户不存在时也走一遍等价耗时的校验，避免用户枚举（provider.go 的要求）。
272→	ntHash := acct.NTHash
273→	ntowf := NTOWFv2(ntHash, m.UserName, m.DomainName)
274→	sbk, blob, ok := VerifyNTLMv2(ntowf, c.serverChallenge, m.NTResponse)
275→	if lookupErr != nil {
276→		ok = false
277→	}
278→
279→	if !ok {
280→		if c.p.opts.Store != nil && c.p.opts.Store.AllowGuest() {
281→			// 降级为 guest：没有可用的 session key，会话不能签名。
282→			c.identity = &Identity{
283→				User:        m.UserName,
284→				Domain:      m.DomainName,
285→				Workstation: m.Workstation,
286→				Guest:       true,
287→			}
288→			c.sessionKey = make([]byte, SessionKeyLen)
289→			c.done = true
290→			return c.wrap(NegAcceptCompleted, nil), true, nil
291→		}
292→		return nil, false, ErrLogonFailure
293→	}
294→
295→	esk, err := ExportedSessionKey(KeyExchangeKey(sbk), m.Flags, m.EncryptedRandomSessionKey)
296→	if err != nil {
297→		return nil, false, err
298→	}
299→
300→	if err := c.verifyMIC(m, blob, esk); err != nil {
301→		return nil, false, err
302→	}
303→
304→	c.identity = &Identity{
305→		User:        acct.User,
306→		Domain:      m.DomainName,
307→		Workstation: m.Workstation,
308→		UID:         acct.UID,
309→		GID:         acct.GID,
310→	}
311→	c.sessionKey = append([]byte(nil), esk[:]...)
312→	c.done = true
313→
314→	// TODO: 待验证 —— 客户端携带 mechListMIC 时，RFC 4178 §5 要求服务端在
315→	// 最终 negTokenResp 里回一个用 NTLM GSS_GetMIC 生成的 mechListMIC。
316→	// smbclient / Windows / macOS 在不回的情况下均能完成认证（SMB 签名本身
317→	// 已覆盖后续报文完整性），故暂不实现。
318→	return c.wrap(NegAcceptCompleted, nil), true, nil
319→}
320→
321→// dummyAccount 用于用户不存在时的等时校验，NTHash 恒为零值。
322→var dummyAccount = &Account{}
323→
324→func (c *ntlmContext) lookup(user, domain string) (*Account, error) {
325→	if c.p.opts.Store == nil {
326→		return dummyAccount, ErrNoSuchUser
327→	}
328→	acct, err := c.p.opts.Store.Lookup(user, domain)
329→	if err != nil || acct == nil {
330→		return dummyAccount, ErrNoSuchUser
331→	}
332→	return acct, nil
333→}
334→
335→// verifyMIC 在客户端声明带 MIC 时校验它（MS-NLMP §3.2.5.1.2）。
336→//
337→// MsvAvFlags 的 0x00000002 位置位表示 AUTHENTICATE_MESSAGE 里有 MIC，
338→// 此时服务端**必须**校验，否则中间人可以篡改 NEGOTIATE 里的标志位降级。
