	if !bytes.Equal(first[12:], []byte{0, 0, 0, 0}) {
		t.Errorf("第一条 SeqNum = % x, want 0", first[12:])
	}
	if !bytes.Equal(second[12:], []byte{1, 0, 0, 0}) {
		t.Errorf("第二条 SeqNum = % x, want 1", second[12:])
	}
	if bytes.Equal(first[4:12], second[4:12]) {
