// 未协商 EXTENDED_SESSIONSECURITY 时没有 SignKey（MS-NLMP §3.4.5.2）。
func TestNoExtendedSessionSecurity(t *testing.T) {
	if k := SignKey(randomSessionKey, Negotiate128, true); k != nil {
		t.Errorf("SignKey = % x, want nil", k)
	}
