241→func TestProviderMIC(t *testing.T) {
242→	const pw = "s3cret"
243→	p := testProvider(t, []config.User{{Name: "alice", Password: pw}}, false, false)
244→
245→	build := func(t *testing.T, tamper bool) error {
246→		t.Helper()
247→		ctx := p.NewContext().(*ntlmContext)
248→		neg := (&NegotiateMessage{Flags: NegotiateUnicode | NegotiateNTLM}).Marshal()
249→		out, _, err := ctx.Step(neg)
250→		if err != nil {
251→			t.Fatalf("NEGOTIATE: %v", err)
252→		}
253→		ch, err := ParseChallengeMessage(out)
254→		if err != nil {
255→			t.Fatalf("CHALLENGE: %v", err)
256→		}
257→
258→		// 客户端在 TargetInfo 里追加 MsvAvFlags(MIC present)。
259→		info := append(AvPairs(nil), ch.TargetInfo...)
260→		var fb [4]byte
261→		binary.LittleEndian.PutUint32(fb[:], AvFlagMICPresent)
262→		info = append(info, AvPair{ID: MsvAvFlags, Value: fb[:]})
263→
264→		ntResp, ntowf := clientNTLMv2(pw, "alice", "WORKGROUP", ch.ServerChallenge,
265→			info, [8]byte{7, 7, 7, 7, 7, 7, 7, 7})
266→		var proof [16]byte
267→		copy(proof[:], ntResp[:16])
268→		esk := SessionBaseKey(ntowf, proof) // 未置 KEY_EXCH，ESK = SessionBaseKey
269→
270→		auth := &AuthenticateMessage{
271→			NTResponse: ntResp, UserName: "alice", DomainName: "WORKGROUP",
272→			Flags: NegotiateUnicode, MICPresent: true,
273→		}
274→		// MIC 计算时 MIC 字段必须为零。
275→		zeroed := auth.Marshal()
276→		mic := ComputeMIC(esk, neg, out, zeroed)
277→		if tamper {
278→			mic[0] ^= 0xFF
279→		}
280→		auth.MIC = mic
281→		_, _, err = ctx.Step(auth.Marshal())
282→		return err
283→	}
284→
285→	if err := build(t, false); err != nil {
286→		t.Fatalf("正确的 MIC 应通过: %v", err)
287→	}
288→	if err := build(t, true); err != ErrLogonFailure {
289→		t.Fatalf("被篡改的 MIC 应拒绝, got %v", err)
290→	}
291→}
