 39→	temp = append(temp, 0, 0, 0, 0) // 结尾 Z(4)
 40→
 41→	proof := ComputeNTProofStr(ntowf, serverChallenge, temp)
 42→	ntResponse = append(append([]byte(nil), proof[:]...), temp...)
 43→	return ntResponse, ntowf
 44→}
