 60→func TestProviderNTLMv2Success(t *testing.T) {
 61→	const pw = "s3cret"
 62→	p := testProvider(t, []config.User{{Name: "alice", Password: pw, UID: 1000, GID: 1000}}, false, false)
 63→	ctx := p.NewContext()
 64→
 65→	// 第一轮：客户端 NEGOTIATE，包在 SPNEGO negTokenInit 里。
 66→	neg := (&NegotiateMessage{
 67→		Flags: NegotiateUnicode | NegotiateRequestTarget | NegotiateNTLM |
 68→			NegotiateExtendedSessionSecurity | NegotiateAlwaysSign | NegotiateKeyExch |
 69→			NegotiateSign | Negotiate128 | Negotiate56,
 70→		Workstation: "CLIENT",
 71→	}).Marshal()
 72→
 73→	mechTypes := derTLV(tagContext0, derTLV(tagSequence, derTLV(tagOID, oidNTLMSSP)))
 74→	mechToken := derTLV(tagContext2, derTLV(tagOctetString, neg))
 75→	initTok := derTLV(tagApplication0, append(derTLV(tagOID, oidSPNEGO),
 76→		derTLV(tagContext0, derTLV(tagSequence, append(mechTypes, mechToken...)))...))
 77→
 78→	out, done, err := ctx.Step(initTok)
 79→	if err != nil {
 80→		t.Fatalf("第一轮: %v", err)
 81→	}
 82→	if done {
 83→		t.Fatal("第一轮不应完成")
 84→	}
 85→	if ctx.Identity() != nil {
 86→		t.Error("未完成时 Identity 应为 nil")
 87→	}
 88→
 89→	ch, err := ParseChallengeMessage(unwrap(t, out))
 90→	if err != nil {
 91→		t.Fatalf("解析 CHALLENGE: %v", err)
 92→	}
 93→	if ch.TargetName != "STUPIDSAMBA" {
 94→		t.Errorf("TargetName = %q", ch.TargetName)
 95→	}
 96→	if !ch.Flags.Has(NegotiateExtendedSessionSecurity) || !ch.Flags.Has(NegotiateTargetInfo) {
 97→		t.Errorf("CHALLENGE Flags = %08x", uint32(ch.Flags))
 98→	}
 99→	if !ch.Flags.Has(NegotiateKeyExch) {
100→		t.Error("客户端请求了 KEY_EXCH，服务端必须镜像该位")
101→	}
102→	// TargetInfo 必须带齐 4 个名字项 + Timestamp。
103→	for _, id := range []AvID{MsvAvNbDomainName, MsvAvNbComputerName,
104→		MsvAvDnsDomainName, MsvAvDnsComputerName, MsvAvTimestamp} {
105→		if _, ok := ch.TargetInfo.Get(id); !ok {
106→			t.Errorf("TargetInfo 缺少 AvId=0x%04x", uint16(id))
107→		}
108→	}
109→
110→	// 第二轮：客户端 AUTHENTICATE。
111→	clientChallenge := [8]byte{1, 2, 3, 4, 5, 6, 7, 8}
112→	ntResp, ntowf := clientNTLMv2(pw, "alice", "WORKGROUP", ch.ServerChallenge,
113→		ch.TargetInfo, clientChallenge)
114→
115→	var proof [16]byte
116→	copy(proof[:], ntResp[:16])
117→	sbk := SessionBaseKey(ntowf, proof)
118→	randomSessionKey := bytes.Repeat([]byte{0x77}, 16)
119→	encKey, err := ExportedSessionKey(sbk, NegotiateKeyExch, randomSessionKey)
120→	if err != nil {
121→		t.Fatalf("RC4: %v", err)
122→	}
123→
124→	auth := &AuthenticateMessage{
125→		NTResponse:                ntResp,
126→		DomainName:                "WORKGROUP",
127→		UserName:                  "alice",
128→		Workstation:               "CLIENT",
129→		EncryptedRandomSessionKey: encKey[:],
130→		Flags:                     ch.Flags,
131→	}
132→	respTok := derTLV(tagContext1, derTLV(tagSequence,
133→		derTLV(tagContext2, derTLV(tagOctetString, auth.Marshal()))))
134→
135→	out, done, err = ctx.Step(respTok)
136→	if err != nil {
137→		t.Fatalf("第二轮: %v", err)
138→	}
139→	if !done {
140→		t.Fatal("第二轮应完成")
141→	}
142→	// 最终 token 应为 accept-completed。
143→	final, err := ParseSPNEGO(out)
144→	if err != nil || final.State != NegAcceptCompleted {
145→		t.Errorf("最终 negState = %v (err=%v)", final.State, err)
146→	}
147→
148→	id := ctx.Identity()
149→	if id == nil || id.User != "alice" || id.UID != 1000 || id.GID != 1000 {
150→		t.Fatalf("Identity = %+v", id)
151→	}
152→	if id.Guest || id.Anonymous {
153→		t.Error("不应是 guest/匿名会话")
154→	}
155→	// ExportedSessionKey 必须等于客户端的 RandomSessionKey。
156→	if !bytes.Equal(ctx.SessionKey(), randomSessionKey) {
157→		t.Errorf("SessionKey = %x, want %x", ctx.SessionKey(), randomSessionKey)
158→	}
159→}
