	initTok := derTLV(tagApplication0, append(derTLV(tagOID, oidSPNEGO),
		derTLV(tagContext0, derTLV(tagSequence, append(
			derTLV(tagContext0, mechListDER),
			derTLV(tagContext2, derTLV(tagOctetString, neg))...)))...))

