cd /workspace && cp /tmp/ntlmssp.go.bak internal/auth/ntlmssp.go && grep -c DBG internal/auth/ntlmssp.go; mkdir -p /tmp/sniff && cat > /tmp/sniff/main.go <<'EOF'
package main

import (
	"encoding/hex"
	"fmt"
	"io"
	"net"
	"os"
)

// 转发 4452 -> 4451，把两个方向的字节流里出现的 SPNEGO negTokenResp/mechListMIC 打出来。
func dump(tag string, b []byte) {
	// 找 A3 xx 04 xx（[3] OCTET STRING，即 mechListMIC）
	for i := 0; i+4 < len(b); i++ {
		if b[i] == 0xA3 && b[i+2] == 0x04 && int(b[i+3]) == 16 && i+4+16 <= len(b) {
			fmt.Printf("%s mechListMIC: %s\n", tag, hex.EncodeToString(b[i+4:i+4+16]))
		}
		// mechTypes: A0 xx 30 xx 06 ...
		if b[i] == 0xA0 && b[i+2] == 0x30 && b[i+4] == 0x06 {
			n := int(b[i+3]) + 2
			if i+2+n <= len(b) {
				fmt.Printf("%s mechTypeList DER: %s\n", tag, hex.EncodeToString(b[i+2:i+2+n]))
			}
		}
	}
}

func pipe(tag string, dst io.Writer, src io.Reader) {
	buf := make([]byte, 65536)
	for {
		n, err := src.Read(buf)
		if n > 0 {
			dump(tag, buf[:n])
			dst.Write(buf[:n])
		}
		if err != nil {
			return
		}
	}
}

func main() {
	l, err := net.Listen("tcp", "127.0.0.1:4452")
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	for {
		c, err := l.Accept()
		if err != nil {
			return
		}
		u, err := net.Dial("tcp", "127.0.0.1:4451")
		if err != nil {
			c.Close()
			continue
		}
		go pipe("C->S", u, c)
		go pipe("S->C", c, u)
	}
}
EOF
