import re
# 1) Context 增加 Encrypted 标志
p='internal/smb/command/context.go'
s=open(p).read()
s=s.replace('''// Suppressed 报告本条消息是否不产生响应。''','''// Encrypted 报告本条请求是否是从 SMB3 TRANSFORM 帧解密出来的。
//
// MS-SMB2 §3.3.5.2.4：加密帧本身已提供完整性保护，客户端不会在密文内层
// 再签名，服务端因此**必须跳过签名校验**，否则强制签名 + 加密会互斥。
func (c *Context) Encrypted() bool { return c.encrypted }

// SetEncrypted 由 internal/server 在解密后标记本条消息。
func (c *Context) SetEncrypted() { c.encrypted = true }

// Suppressed 报告本条消息是否不产生响应。''')
s=s.replace('''func (c *Context) Suppressed() bool { return c.suppress }''','''func (c *Context) Suppressed() bool { return c.suppress }''')
open(p,'w').write(s)

# 加字段
s=open(p).read()
m=re.search(r'\n\tsuppress\s+bool\n', s)
if m:
    s=s[:m.end()]+"\tencrypted bool\n"+s[m.end():]
else:
    # 退化：找 struct Context {
    i=s.index('type Context struct {')
    j=s.index('\n', i)
    s=s[:j+1]+"\tencrypted bool\n"+s[j+1:]
open(p,'w').write(s)
PY
