  1→package crypto
  2→
  3→import (
  4→	"bytes"
  5→	"crypto/hmac"
  6→	"crypto/sha256"
  7→	"testing"
  8→)
  9→
 10→// KDF 的输入拼装必须是 [i]_32 || Label || 0x00 || Context || [L]_32。
 11→// 这里用手工拼装的字节串独立算一遍 HMAC-SHA256 来交叉验证。
 12→func TestKDF_InputLayout(t *testing.T) {
 13→	ki := mustHex(t, "000102030405060708090a0b0c0d0e0f")
 14→	label := []byte("SMB2AESCMAC\x00")
 15→	context := []byte("SmbSign\x00")
 16→
 17→	var input []byte
 18→	input = append(input, 0x00, 0x00, 0x00, 0x01) // [i]_32 = 1
 19→	input = append(input, label...)
 20→	input = append(input, 0x00)
 21→	input = append(input, context...)
 22→	input = append(input, 0x00, 0x00, 0x00, 0x80) // [L]_32 = 128
 23→
 24→	h := hmac.New(sha256.New, ki)
 25→	h.Write(input)
 26→	want := h.Sum(nil)[:16]
 27→
 28→	if got := KDF(ki, label, context, 128); !bytes.Equal(got, want) {
 29→		t.Errorf("KDF = %x, want %x", got, want)
 30→	}
 31→
 32→	// L = 256 时 HMAC-SHA256 一次迭代刚好 32 字节。
 33→	input[len(input)-2] = 0x01
 34→	input[len(input)-1] = 0x00
 35→	h.Reset()
 36→	h.Write(input)
 37→	if got := KDF(ki, label, context, 256); !bytes.Equal(got, h.Sum(nil)) {
 38→		t.Errorf("KDF(256) mismatch")
 39→	}
 40→}
 41→
 42→// Label / Context 大小写敏感且带结尾 NUL；"ServerIn " 结尾有空格。
 43→// 这些常量一旦写错，与真实客户端的签名/加密就完全对不上，故单独钉住。
 44→func TestKDFLabels(t *testing.T) {
 45→	cases := []struct {
 46→		got  []byte
 47→		want string
 48→	}{
 49→		{labelSMB2AESCMAC, "SMB2AESCMAC\x00"},
 50→		{contextSmbSign, "SmbSign\x00"},
 51→		{labelSMB2APP, "SMB2APP\x00"},
 52→		{contextSmbRpc, "SmbRpc\x00"},
 53→		{labelSMB2AESCCM, "SMB2AESCCM\x00"},
 54→		{contextServerOut, "ServerOut\x00"},
 55→		{contextServerIn, "ServerIn \x00"},
 56→		{labelSMBSigningKey, "SMBSigningKey\x00"},
 57→		{labelSMBAppKey, "SMBAppKey\x00"},
 58→		{labelSMBS2CCipherKey, "SMBS2CCipherKey\x00"},
 59→		{labelSMBC2SCipherKey, "SMBC2SCipherKey\x00"},
 60→	}
 61→	for _, tc := range cases {
 62→		if string(tc.got) != tc.want {
 63→			t.Errorf("label %q != %q", tc.got, tc.want)
 64→		}
 65→	}
 66→}
 67→
 68→func TestDerivedKeys(t *testing.T) {
 69→	sessionKey := mustHex(t, "000102030405060708090a0b0c0d0e0f")
 70→	preauth := make([]byte, 64)
 71→	for i := range preauth {
 72→		preauth[i] = byte(i)
 73→	}
 74→
 75→	// 2.x 不派生，直接用 SessionKey。
 76→	for _, d := range []uint16{DialectSMB202, DialectSMB210} {
 77→		if got := SigningKey(d, sessionKey, nil); !bytes.Equal(got, sessionKey) {
 78→			t.Errorf("SigningKey(%#04x) = %x, want session key", d, got)
 79→		}
 80→	}
 81→
 82→	// 3.0 / 3.0.2 用固定 Label/Context，与 preauth 无关。
 83→	a := SigningKey(DialectSMB300, sessionKey, preauth)
 84→	b := SigningKey(DialectSMB302, sessionKey, nil)
 85→	if !bytes.Equal(a, b) {
 86→		t.Error("3.0 与 3.0.2 的 SigningKey 应当一致且不依赖 preauth")
 87→	}
 88→	if len(a) != 16 {
 89→		t.Fatalf("SigningKey 长度 = %d", len(a))
 90→	}
 91→
 92→	// 3.1.1 依赖 preauth 哈希。
 93→	c := SigningKey(DialectSMB311, sessionKey, preauth)
 94→	if bytes.Equal(a, c) {
 95→		t.Error("3.1.1 与 3.0 的 SigningKey 不应相同")
 96→	}
 97→	other := make([]byte, 64)
 98→	if bytes.Equal(c, SigningKey(DialectSMB311, sessionKey, other)) {
 99→		t.Error("3.1.1 SigningKey 必须随 preauth 变化")
100→	}
101→
102→	// 四种密钥必须互不相同。
103→	keys := map[string][]byte{
104→		"sign": SigningKey(DialectSMB311, sessionKey, preauth),
105→		"app":  ApplicationKey(DialectSMB311, sessionKey, preauth),
106→		"s2c":  ServerOutKey(DialectSMB311, sessionKey, preauth, 16),
107→		"c2s":  ServerInKey(DialectSMB311, sessionKey, preauth, 16),
108→	}
109→	for n1, k1 := range keys {
110→		for n2, k2 := range keys {
111→			if n1 < n2 && bytes.Equal(k1, k2) {
112→				t.Errorf("%s 与 %s 派生出了相同的密钥", n1, n2)
113→			}
114→		}
115→	}
116→
117→	// AES-256 场景：仅 3.1.1 允许 32 字节。
118→	if got := ServerOutKey(DialectSMB311, sessionKey, preauth, 32); len(got) != 32 {
119→		t.Errorf("AES-256 ServerOutKey 长度 = %d, want 32", len(got))
120→	}
121→	if got := ServerOutKey(DialectSMB300, sessionKey, preauth, 32); len(got) != 16 {
122→		t.Errorf("3.0 ServerOutKey 长度 = %d, want 16", len(got))
123→	}
124→	// S→C 与 C→S 在 3.0 下靠 Context 区分。
125→	if bytes.Equal(
126→		ServerOutKey(DialectSMB300, sessionKey, nil, 16),
127→		ServerInKey(DialectSMB300, sessionKey, nil, 16),
128→	) {
129→		t.Error("3.0 的 ServerOut/ServerIn 密钥不应相同")
130→	}
131→}
